def pieces_of(out):
    import numpy as np
    o=np.array(out); H,W=o.shape
    seen=np.zeros_like(o,bool); res=[]
    for r in range(H):
        for c in range(W):
            if o[r,c] and not seen[r,c]:
                col=int(o[r,c]); st=[(r,c)]; comp=[]
                while st:
                    a,b_=st.pop()
                    if 0<=a<H and 0<=b<W and o[a,b]==col and not seen[a,b]:
                        seen[a,b]=True; comp.append((a,b))
                        st+=[(a+1,b),(a-1,b),(a,b+1),(a,b-1)]
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                res.append((col,len(comp),min(rs),max(cs)))
    return sorted(res)
